def longestPrefixSuffixPalindrome(s):
    n = len(s)
    k = 0
    while 2 * k + 1 < n and s[k] == s[n - 1 - k]:
        k += 1
    if 2 * k + 1 >= n:
        return n
    m = s[k:n - k]

    def pal_prefix(x):
        t = x + '#' + x[::-1]
        pi = [0] * len(t)
        for i in range(1, len(t)):
            j = pi[i - 1]
            while j and t[i] != t[j]:
                j = pi[j - 1]
            if t[i] == t[j]:
                j += 1
            pi[i] = j
        return pi[-1]

    return 2 * k + max(pal_prefix(m), pal_prefix(m[::-1]))
